void UntrustedProjectorPageHandlerAsyncWaiter::GetNewScreencastPrecondition(
    ::ash::NewScreencastPrecondition* out_precondition) {
  base::RunLoop loop;
  proxy_->GetNewScreencastPrecondition(
      base::BindOnce(
          [](base::RunLoop* loop,
             ::ash::NewScreencastPrecondition* out_precondition
,
             const ::ash::NewScreencastPrecondition& precondition) {*out_precondition = std::move(precondition);
            loop->Quit();
          },
          &loop,
          out_precondition));
  loop.Run();
}

